type ViewKey = 'dashboard' | 'jobs' | 'applications' | 'confirmed' | 'posts' | 'users' | 'payments' | 'permissions' | 'analytics' | 'settings';
type JobStatus = 'Draft' | 'Review' | 'Published' | 'Paused' | 'Archived';
type ApplicationStatus = 'APPLIED' | 'REVIEWING' | 'SHORTLISTED' | 'INTERVIEW' | 'SELECTED' | 'CONFIRMED' | 'HIRED' | 'REJECTED';
type PaymentStatus = 'COMPLETED' | 'PENDING' | 'REFUNDED' | 'FAILED';
type IconType = typeof LayoutDashboard;

type Job = { id: string | number; title: string; employer: string; location: string; type: string; salary: string; applications: number; status: JobStatus; deadline: string; featured: boolean };
type Application = { id: number; name: string; role: string; job: string; skills: string[]; experience: string; score: number; status: ApplicationStatus; date: string };
type Payment = { id: string; party: string; task: string; amount: string; date: string; status: PaymentStatus; escrow: string };

